import sys
import json

# kind codes
ZERO, FIN, INF, NAN = 0, 1, 2, 3
FLAG_ORDER = ("invalid", "overflow", "underflow", "inexact")


class Ctx:
    __slots__ = ("ebits", "fbits", "bias", "Eall", "emin", "emax",
                 "tbits", "fmask", "emask", "ftop", "F", "vmask", "sbit")

    def __init__(self, ebits, fbits):
        self.ebits = ebits
        self.fbits = fbits
        self.bias = (1 << (ebits - 1)) - 1
        self.Eall = (1 << ebits) - 1
        self.emin = 1 - self.bias
        self.emax = self.Eall - 1 - self.bias
        self.tbits = 1 + ebits + fbits
        self.fmask = (1 << fbits) - 1
        self.emask = (1 << ebits) - 1
        self.ftop = 1 << (fbits - 1)
        self.F = 1 << fbits
        self.vmask = (1 << self.tbits) - 1
        self.sbit = 1 << (ebits + fbits)


def decode(ctx, v):
    f = v & ctx.fmask
    e = (v >> ctx.fbits) & ctx.emask
    s = 1 if (v & ctx.sbit) else 0
    if e == ctx.Eall:
        if f == 0:
            return (INF, s)
        return (NAN, s, (f & ctx.ftop) == 0)
    if e == 0:
        if f == 0:
            return (ZERO, s)
        return (FIN, s, f, ctx.emin - ctx.fbits)  # subnormal: f * 2^(1-bias-fbits)
    return (FIN, s, ctx.F | f, e - ctx.bias - ctx.fbits)


def cmp_pow2(n, q_exp, p):
    # compare n * 2**q_exp  vs  2**p ; n >= 0 integer
    if n == 0:
        return -1
    k = p - q_exp
    if k >= 0:
        t = 1 << k
        if n < t:
            return -1
        if n > t:
            return 1
        return 0
    return 1


def solve(req):
    ctx = Ctx(req["ebits"], req["fbits"])

